<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$query=function(array $change=[])use($filters):string{return http_build_query([...$filters,...$change]);}; ?>
<div class="page-heading"><div><h1>Products</h1><p>Search and manage the core catalog.</p></div><a class="button" href="/admin/products/create">Add product</a></div><?php if($flash):?><p class="flash flash-<?= $e($flash['type']) ?>" role="status"><?= $e($flash['message']) ?></p><?php endif;?>
<form class="panel filters" method="get" action="/admin/products"><label>Search<input name="q" value="<?= $e($filters['q']) ?>" maxlength="100" placeholder="Name or code"></label><label>Brand<select name="brand_id"><option value="">All</option><?php foreach($brands as $b):?><option value="<?= $e($b['id']) ?>" <?= $filters['brand_id']==$b['id']?'selected':'' ?>><?= $e($b['name']) ?></option><?php endforeach;?></select></label><label>Category<select name="category_id"><option value="">All</option><?php foreach($categories as $c):?><option value="<?= $e($c['id']) ?>" <?= $filters['category_id']==$c['id']?'selected':'' ?>><?= $e($c['name']) ?></option><?php endforeach;?></select></label><label>Status<select name="status"><option value="">All</option><option value="active" <?= $filters['status']==='active'?'selected':'' ?>>Active</option><option value="hidden" <?= $filters['status']==='hidden'?'selected':'' ?>>Hidden</option></select></label><button type="submit">Filter</button><a href="/admin/products">Clear</a></form>
<section class="panel table-wrap"><table><thead><tr><th>Product</th><th>Code</th><th>Brand</th><th>Category</th><th>Price</th><th>Status</th><th>Featured</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($result['items'] as $p):?><tr><td><?= $e($p['name']) ?></td><td><?= $e($p['code']??'—') ?></td><td><?= $e($p['brand_name']) ?></td><td><?= $e($p['category_name']) ?></td><td><?= $p['price']===null?'—':$e(number_format((float)$p['price'],2,'.',',')) ?></td><td><span class="badge <?= (int)$p['is_active']===1?'active':'hidden' ?>"><?= (int)$p['is_active']===1?'Active':'Hidden' ?></span></td><td><?= (int)$p['is_featured']===1?'Yes':'No' ?></td><td><?= $e($p['updated_at']) ?></td><td class="actions"><a href="/admin/products/<?= $e($p['id']) ?>/edit">Edit</a><form method="post" action="/admin/products/<?= $e($p['id']) ?>/status"><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><input type="hidden" name="is_active" value="<?= (int)$p['is_active']===1?'0':'1' ?>"><button class="link-button" type="submit"><?= (int)$p['is_active']===1?'Hide':'Activate' ?></button></form><form method="post" action="/admin/products/<?= $e($p['id']) ?>/delete" data-confirm="Permanently delete this product and dependent rows? Hiding is preferable for discontinued products."><input type="hidden" name="_csrf" value="<?= $e($csrfToken) ?>"><button class="link-button danger" type="submit">Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if($result['items']===[]):?><p>No products match these filters.</p><?php endif;?></section>
<?php if($result['pages']>1):?><nav class="pagination" aria-label="Product pages"><?php for($i=1;$i<=$result['pages'];$i++):?><a class="<?= $i===$result['page']?'current':'' ?>" href="/admin/products?<?= $e($query(['page'=>$i])) ?>"><?= $i ?></a><?php endfor;?></nav><?php endif;?>
